package org.sleepwell.app;
import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
/** Typed API staging, stale-review fencing and recoverable acknowledged preference commits. */
final class SettingsProfilePersistence {
 static final Object LOCK=new Object();
 static final String MAIN="sleepwell",NARRATION="guided_narration_v1";
 static final Set<String> MAIN_KEYS=Set.of(Appearance.AUTO,Appearance.THEME,Appearance.SIZE,Appearance.MOTION,Appearance.CONTRAST,"goal","bedtime","wakeTime","windDownMinutes","bedReminderAdvance","bedReminder","smartBedtime","noAlarmBedtime","smartBedtimeRepeatMinutes","smartBedtimeRepeatLimit","planRevision","mixRevision","mixVersion","mixPrimary","mixUri","mixTitle","mixPlaylist","mixAmbientRotation","mixBinauralCarrier","mixBinauralBeat","mixPrimaryGain","mixBrownGain","mixMinutes","mixFade","mixWithTracking","lullaby","lullabyMinutes");
 static Set<String> keys(String file){if(MAIN.equals(file))return MAIN_KEYS;if(NARRATION.equals(file))return Set.of("rate","pitch");throw new IllegalArgumentException("Unsupported profile preferences file");}
 private static AtomicFile journal(Context context){return new AtomicFile(new File(context.getFilesDir(),"settings-profile-apply-v1.json"));}
 static boolean interrupted(Context context){return journal(context).getBaseFile().exists()||new File(journal(context).getBaseFile()+".bak").exists();}
 static void idle(Context context,long admission,SettingsProfile profile){BackupRuntime.requireIdle(context,admission);SleepSoundService.Snapshot sound=SleepSoundService.snapshot();if(sound!=null&&(sound.state==SoundPlayback.State.LOADING||sound.state==SoundPlayback.State.PLAYING||sound.state==SoundPlayback.State.PAUSED))throw new IllegalStateException("Stop the sleep-sound player before applying a settings profile.");if(profile!=null&&profile.plan!=null){SleepPlan current=SleepPlans.load(context);if(current.reminder||current.smartBedtime||current.noAlarmBedtime||Prefs.flag(context,"bedGuard"))throw new IllegalStateException("Turn off bedtime reminders, smart bedtime and Bedtime guard before importing a sleep plan.");try(Store store=Records.open(context)){for(Alarm alarm:store.alarms())if(alarm.enabled&&(alarm.bedtimeInvalid||alarm.bedtime.custom()))throw new IllegalStateException("Review and disable per-alarm bedtime reminder overrides before importing a sleep plan.");}}}
 private static Map<String,Object> read(Context context,String file){Map<String,?> all=context.getSharedPreferences(file,Context.MODE_PRIVATE).getAll();Map<String,Object> selected=new TreeMap<>();for(String key:keys(file))if(all.containsKey(key)){Object value=all.get(key);if(!(value instanceof Boolean||value instanceof Integer||value instanceof Long||value instanceof String))throw new IllegalStateException("A supported preference is unreadable: "+key);selected.put(key,value);}return selected;}
 static String fingerprint(Context context){try{JSONObject files=new JSONObject();for(String file:List.of(MAIN,NARRATION))files.put(file,encoded(read(context,file)));byte[] bytes=MessageDigest.getInstance("SHA-256").digest(files.toString().getBytes(StandardCharsets.UTF_8));return java.util.Base64.getEncoder().encodeToString(bytes);}catch(NoSuchAlgorithmException|JSONException impossible){throw new IllegalStateException(impossible);}}
 private static JSONObject encoded(Map<String,Object> values)throws JSONException{JSONObject out=new JSONObject();for(String key:new TreeSet<>(values.keySet())){Object value=values.get(key);out.put(key,new JSONObject().put("kind",value==null?"absent":value instanceof Boolean?"boolean":value instanceof Integer?"integer":value instanceof Long?"long":"string").put("value",value==null?JSONObject.NULL:value));}return out;}
 private static Map<String,Object> decoded(String file,JSONObject row)throws JSONException{Map<String,Object> values=new TreeMap<>();for(Iterator<String> iterator=row.keys();iterator.hasNext();){String key=iterator.next();if(!keys(file).contains(key))throw new JSONException("Unsupported recovery preference");JSONObject field=row.getJSONObject(key);SettingsProfile.keys(field,"kind","value");String type=SensorProvenance.text(field,"kind");Object value=switch(type){case "absent"->{if(!field.isNull("value"))throw new JSONException("Invalid recovery absence");yield null;}case "boolean"->SettingsProfile.flag(field,"value");case "integer"->Math.toIntExact(SensorProvenance.whole(field,"value"));case "long"->SensorProvenance.whole(field,"value");case "string"->SensorProvenance.text(field,"value");default->throw new JSONException("Invalid recovery preference type");};values.put(key,value);}return values;}
 private static void write(Context context,String file,Map<String,Object> values){SharedPreferences.Editor edit=context.getSharedPreferences(file,Context.MODE_PRIVATE).edit();for(Map.Entry<String,Object> field:values.entrySet()){String key=field.getKey();if(!keys(file).contains(key))throw new IllegalStateException("Unsupported staged setting");Object value=field.getValue();if(value==null)edit.remove(key);else if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Integer)edit.putInt(key,(Integer)value);else if(value instanceof Long)edit.putLong(key,(Long)value);else if(value instanceof String)edit.putString(key,(String)value);else throw new IllegalStateException("Unsupported staged value");}if(!edit.commit())throw new IllegalStateException("Preference storage did not acknowledge the write.");}
 private static final class Stage extends ContextWrapper {final Map<String,Memory> files=new HashMap<>();Stage(Context context){super(context);for(String name:List.of(MAIN,NARRATION))files.put(name,new Memory(read(context,name)));}@Override public SharedPreferences getSharedPreferences(String name,int mode){Memory value=files.get(name);if(value==null)throw new IllegalStateException("Typed settings used an unsupported preferences file");return value;}@Override public Context getApplicationContext(){return this;}}
 static String apply(Context context,SettingsProfile profile,String expected,long admission)throws Exception{synchronized(LOCK){if(interrupted(context))throw new IllegalStateException("Review the interrupted settings operation first.");idle(context,admission,profile);if(!fingerprint(context).equals(expected))throw new IllegalStateException("Settings changed after this review. Refresh the review before applying.");Stage stage=new Stage(context);
  if(profile.appearance!=null){JSONObject a=profile.appearance;Appearance.save(stage,SettingsProfile.flag(a,"automatic"),SettingsProfile.number(a,"theme",0,2),SettingsProfile.number(a,"textSize",0,2),SettingsProfile.flag(a,"reduceMotion"),SettingsProfile.flag(a,"highContrast"));}
  if(profile.plan!=null){SleepPlan plan=profile.sleepPlan();plan.revision=SleepPlans.load(stage).revision;SleepPlans.save(stage,plan);}
  if(profile.sounds!=null)SoundPreferences.save(stage,profile.soundMix());if(profile.narration!=null)profile.narrationSettings().save(stage);
  JSONObject before=new JSONObject(),after=new JSONObject();for(String name:List.of(MAIN,NARRATION)){Memory memory=stage.files.get(name);if(memory.changed.isEmpty())continue;Map<String,Object> original=read(context,name),prior=new TreeMap<>();for(String key:memory.changed.keySet())prior.put(key,original.get(key));before.put(name,encoded(prior));after.put(name,encoded(memory.changed));}
  JSONObject receipt=new JSONObject().put("version",1).put("before",before).put("after",after);byte[] bytes=receipt.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>SettingsProfile.LIMIT)throw new IllegalStateException("Settings recovery journal is too large");idle(context,admission,profile);if(!fingerprint(context).equals(expected))throw new IllegalStateException("Settings changed before commit. Refresh this review.");AtomicFile record=journal(context);FileOutputStream output=null;try{output=record.startWrite();output.write(bytes);record.finishWrite(output);}catch(Exception failure){if(output!=null)record.failWrite(output);throw failure;}
  if(!fingerprint(context).equals(expected)){record.delete();throw new IllegalStateException("Settings changed while the recovery copy was being saved. No settings were applied; refresh this review.");}
  try{for(String name:List.of(MAIN,NARRATION)){idle(context,admission,profile.plan==null?profile:new SettingsProfile(profile.appearance,null,profile.sounds,profile.narration));Memory memory=stage.files.get(name);if(!memory.changed.isEmpty()){Map<String,Object> prior=decoded(name,before.getJSONObject(name)),actual=read(context,name);for(String key:prior.keySet())if(!Objects.equals(prior.get(key),actual.get(key)))throw new IllegalStateException("A setting changed immediately before its write. Review the interrupted operation instead of overwriting that choice.");write(context,name,memory.changed);}}record.delete();return "Reviewed settings applied. Automatic playback and imported bedtime reminders remain off. No recording, sound, alarm or permission request was started.";}catch(Exception failure){try{rollback(context,admission);}catch(Exception rollback){throw new IllegalStateException("Apply did not finish and rollback is unconfirmed. Some supported settings may have changed. Review Restore previous settings here. "+message(failure)+" "+message(rollback));}throw new IllegalStateException("Settings could not be applied; previous supported values were restored. "+message(failure));}
 }}
 static String rollback(Context context,long admission)throws Exception{synchronized(LOCK){idle(context,admission,null);AtomicFile file=journal(context);String text;try(InputStream in=file.openRead()){text=SettingsProfileJson.read(in,()->true);}JSONObject row=new JSONObject(text);SettingsProfile.keys(row,"version","before","after");if(SensorProvenance.whole(row,"version")!=1)throw new JSONException("Unsupported recovery version");JSONObject before=row.getJSONObject("before"),after=row.getJSONObject("after");if(before.length()!=after.length()||before.length()>2)throw new JSONException("Invalid recovery files");if(before.has(MAIN)&&before.getJSONObject(MAIN).has("goal"))idle(context,admission,new SettingsProfile(null,new JSONObject(),null,null));for(Iterator<String> it=before.keys();it.hasNext();){String name=it.next();Map<String,Object> old=decoded(name,before.getJSONObject(name)),candidate=decoded(name,after.getJSONObject(name)),current=read(context,name);if(!old.keySet().equals(candidate.keySet()))throw new JSONException("Invalid recovery keys");for(String key:old.keySet())if(!Objects.equals(current.get(key),candidate.get(key))&&!Objects.equals(current.get(key),old.get(key)))throw new IllegalStateException("A supported setting changed after the interrupted apply. Previous values were kept in the recovery journal; automatic rollback would overwrite that newer choice.");}
  for(Iterator<String> it=before.keys();it.hasNext();){String name=it.next();idle(context,admission,null);write(context,name,decoded(name,before.getJSONObject(name)));}file.delete();return "Previous supported settings restored. Records, alarms and excluded preferences were not replaced.";}}
 static String message(Exception error){String text=error.getMessage();return text==null?"Settings operation failed.":text.length()>300?text.substring(0,300):text;}
 /** In-memory SharedPreferences collects only values emitted by existing typed save APIs. */
 private static final class Memory implements SharedPreferences {final Map<String,Object> values,changed=new TreeMap<>();Memory(Map<String,Object> values){this.values=new HashMap<>(values);}public Map<String,?> getAll(){return new HashMap<>(values);}public boolean contains(String key){return values.containsKey(key);}private Object value(String key,Object fallback){return values.containsKey(key)?values.get(key):fallback;}public String getString(String key,String fallback){return (String)value(key,fallback);}public Set<String> getStringSet(String key,Set<String> fallback){throw new UnsupportedOperationException();}public int getInt(String key,int fallback){return (Integer)value(key,fallback);}public long getLong(String key,long fallback){return (Long)value(key,fallback);}public float getFloat(String key,float fallback){throw new UnsupportedOperationException();}public boolean getBoolean(String key,boolean fallback){return (Boolean)value(key,fallback);}public void registerOnSharedPreferenceChangeListener(OnSharedPreferenceChangeListener listener){}public void unregisterOnSharedPreferenceChangeListener(OnSharedPreferenceChangeListener listener){}public Editor edit(){return new Editor(){final Map<String,Object> pending=new HashMap<>();private Editor set(String key,Object value){pending.put(key,value);return this;}public Editor putString(String key,String value){return set(key,value);}public Editor putStringSet(String key,Set<String> value){throw new UnsupportedOperationException();}public Editor putInt(String key,int value){return set(key,value);}public Editor putLong(String key,long value){return set(key,value);}public Editor putFloat(String key,float value){throw new UnsupportedOperationException();}public Editor putBoolean(String key,boolean value){return set(key,value);}public Editor remove(String key){return set(key,null);}public Editor clear(){throw new UnsupportedOperationException();}public boolean commit(){for(Map.Entry<String,Object> field:pending.entrySet()){changed.put(field.getKey(),field.getValue());if(field.getValue()==null)values.remove(field.getKey());else values.put(field.getKey(),field.getValue());}return true;}public void apply(){commit();}};}}
 private SettingsProfilePersistence(){}
}
